const output = [];

for (const item of items) {
  const parts = item.json.payload?.parts || [];

  for (const part of parts) {
    if (part?.body?.attachmentId) {
      output.push({
        json: part.body
      });
    }
  }
}

return output;

if (!$json.data) {
  throw new Error('No base64 data found in JSON input');
}

// Decode base64 string from JSON
const text = Buffer.from($json.data, 'base64').toString('utfREDACTED');

// Remove line breaks inside quoted fields
const cleaned = text.replace(/"([^"]*)"/gs, m =>
  m.replace(/\r?\n/g, ' ')
);

// Remove empty lines
const finalText = cleaned
  .split('\n')
  .filter(l => l.trim() !== '')
  .join('\n');

// Return as proper binary so CSV node can read it
return [{
  binary: {
    data: {
      data: Buffer.from(finalText).toString('base64'),
      mimeType: 'text/csv',
      fileName: 'cleaned.csv',
    },
  },
}];

const items = $input.all();

return items.map(item => {
  const cleaned = {};
  for (const [key, value] of Object.entries(item.json)) {
    const newKey = key.trim().replace(/^[\/\\]+|[\/\\]+$/g, '').trim();
    cleaned[newKey] = value;
  }
  return { json: cleaned };
});
